class Solution:
    def countExcellentPairs(self, nums: List[int], k: int) -> int:
        def popcount(x):
            return bin(x)[2:].count('1')

        cnt = collections.Counter(popcount(x) for x in set(nums))
        return sum(cnt[i]*cnt[j] for i in cnt.keys() for j in cnt.keys() if i+j >= k)

